import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Mail, Bell } from 'lucide-react';
import axios from 'axios';

const StickyCTA = () => {
  const [showSticky, setShowSticky] = useState(false);
  const [isDismissed, setIsDismissed] = useState(false);
  const [email, setEmail] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubscribed, setIsSubscribed] = useState(false);

  useEffect(() => {
    // Check if banner was already dismissed in this session
    const wasDismissed = sessionStorage.getItem('notificationBannerDismissed');
    if (wasDismissed) {
      return;
    }

    const handleScroll = () => {
      // Show sticky CTA after user scrolls past hero section
      const heroHeight = window.innerHeight;
      const scrollPosition = window.scrollY;

      if (scrollPosition > heroHeight * 0.8 && !isDismissed) {
        setShowSticky(true);
      } else {
        setShowSticky(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [isDismissed]);

  const handleDismiss = () => {
    setIsDismissed(true);
    setShowSticky(false);
    sessionStorage.setItem('notificationBannerDismissed', 'true');
  };

  const handleSubscribe = async (e) => {
    e.preventDefault();
    if (!email) return;

    setIsSubmitting(true);

    try {
      await axios.post('/api/exit-intent', {
        email,
        firstName: 'Newsletter Subscriber'
      });

      setIsSubscribed(true);
      setTimeout(() => {
        handleDismiss();
      }, 2000);
    } catch (error) {
      console.error('Error subscribing:', error);
      alert('Es gab einen Fehler beim Abonnieren. Bitte versuchen Sie es erneut.');
      setIsSubmitting(false);
    }
  };

  return (
    <AnimatePresence>
      {showSticky && (
        <motion.div
          initial={{ y: 100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 100, opacity: 0 }}
          className="fixed bottom-0 left-0 right-0 z-40"
        >
          {/* Mobile: Full-width bar */}
          <div className="block sm:hidden">
            <div className="bg-coral-500 text-white px-4 py-3">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center space-x-2">
                  <Bell className="w-5 h-5" />
                  <p className="text-sm font-semibold">Verpasse nie wieder fesche Last Minute Trips</p>
                </div>
                <button
                  onClick={handleDismiss}
                  className="text-white/70 hover:text-white p-1"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              {isSubscribed ? (
                <div className="text-center py-2">
                  <p className="text-sm">🎉 Du bist dabei! Check dein Postfach.</p>
                </div>
              ) : (
                <form onSubmit={handleSubscribe} className="flex gap-2">
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="Deine E-Mail"
                    className="flex-1 px-3 py-2 rounded-lg text-gray-900 text-sm"
                    required
                  />
                  <button
                    type="submit"
                    disabled={isSubmitting}
                    className="bg-white text-coral-500 px-4 py-2 rounded-lg text-sm font-semibold disabled:opacity-50 flex items-center space-x-1"
                  >
                    <Mail className="w-4 h-4" />
                    <span>{isSubmitting ? '...' : 'Anmelden'}</span>
                  </button>
                </form>
              )}
            </div>
          </div>

          {/* Desktop: Card-style */}
          <div className="hidden sm:block">
            <div className="max-w-2xl mx-auto mb-6">
              <div className="bg-coral-50 rounded-lg shadow-2xl border border-coral-200 p-4">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center space-x-3">
                    <Bell className="w-6 h-6 text-coral-600" />
                    <div>
                      <p className="text-lg font-semibold text-gray-900">
                        Verpasse nie wieder fesche Last Minute Trips
                      </p>
                      <p className="text-sm text-gray-600">
                        Erhalte exklusive Angebote direkt in dein Postfach
                      </p>
                    </div>
                  </div>

                  <button
                    onClick={handleDismiss}
                    className="text-gray-400 hover:text-gray-600 p-1"
                  >
                    <X className="w-5 h-5" />
                  </button>
                </div>

                {isSubscribed ? (
                  <div className="text-center py-4">
                    <p className="text-coral-600 font-semibold">🎉 Du bist dabei! Check dein Postfach.</p>
                  </div>
                ) : (
                  <form onSubmit={handleSubscribe} className="flex gap-3">
                    <input
                      type="email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      placeholder="Deine E-Mail-Adresse"
                      className="flex-1 px-4 py-3 rounded-lg border border-coral-300 text-gray-900 focus:ring-2 focus:ring-coral-500 focus:border-coral-500"
                      required
                    />
                    <button
                      type="submit"
                      disabled={isSubmitting}
                      className="bg-coral-500 text-white px-6 py-3 rounded-lg font-semibold disabled:opacity-50 flex items-center space-x-2 hover:bg-coral-600 transition-colors"
                    >
                      <Mail className="w-4 h-4" />
                      <span>{isSubmitting ? 'Wird gesendet...' : 'Benachrichtigen'}</span>
                    </button>
                  </form>
                )}
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default StickyCTA;
